$cfg = Get-Item "C:\Users\Administrator\.dsh\profiles\web\cordis.patch.yml"
Write-Host "config mtime: $($cfg.LastWriteTime)"
$gw = Get-Item "C:\Users\Administrator\.dsh\mcp-gateway\cordis.patch.yml"
Write-Host "gateway cfg mtime: $($gw.LastWriteTime)"
$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
# For sessions WITH ov tools, what's the newest session start (titleInput/last activity)? Check by file LastWriteTime
$withOv = Get-ChildItem $dir -Filter "session-*.json"
$recent=@(); $old=@()
foreach($f in $withOv){
 try{
  $j=Get-Content $f.FullName -Raw|ConvertFrom-Json
  $hs=$j.record.rows.contextHeaders.val.headers
  if(-not $hs){continue}
  $t=$hs[0].tools; if(-not $t){continue}
  $has=@($t|Where-Object{$_.name -like 'mcp__openviking__*'}).Count -gt 0
  if($has){ $recent += $f.LastWriteTime } else { $old += $f.LastWriteTime }
 }catch{}
}
Write-Host "WITH ov tools: $($recent.Count) sessions, newest file mtime: $(($recent|Sort-Object -Descending)[0])"
Write-Host "WITHOUT ov    : $($old.Count) sessions, newest file mtime: $(($old|Sort-Object -Descending)[0])"

# (2) memory recall/commit unaffected: check recent post-config sessions for openviking recall/commit activity
# Look at projcache contextTimeline / inject events for openviking markers in sessions after 14:08
$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$post = Get-ChildItem $dir -Filter "session-*.json" | Where-Object { $_.LastWriteTime -gt (Get-Date "2026-11-14 14:08:25") }
Write-Host "sessions created/updated after config change (14:08): $($post.Count)"
foreach($f in $post){
  $j = Get-Content $f.FullName -Raw | ConvertFrom-Json
  $t = $j.record.rows.title.val
  if($t){$t=$t.Substring(0,[Math]::Min(30,$t))}
  $hs=$j.record.rows.contextHeaders.val.headers
  $tc = if($hs){$hs[0].tools.Count}else{0}
  Write-Host ("  {0} mtime={1:HH:mm} tools={2} title={3}" -f $f.Name.Substring(8,8),$f.LastWriteTime,$tc,$t)
}

